      ::mojo::PendingRemote<SubinterfaceClient> p_client{};
      TestMessageTarget_RequestSubinterface_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_receiver =
            input_data_view.TakeReceiver<decltype(p_receiver)>();
      }
      if (success) {
        p_client =
            input_data_view.TakeClient<decltype(p_client)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            TestMessageTarget::Name_, 7, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
