// static
bool InterfaceVersionTestStubDispatch::AcceptWithResponder(
    InterfaceVersionTest* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::internal::ResponderThunk> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (static_cast<messages::InterfaceVersionTest>(message->header()->name)) {
    case messages::InterfaceVersionTest::kFoo: {
      internal::InterfaceVersionTest_Foo_Params_Data* params =
          reinterpret_cast<
              internal::InterfaceVersionTest_Foo_Params_Data*>(
                  message->mutable_payload());
      

      // Validation for InterfaceVersionTest.0
      bool success = true;
      int32_t p_x{};
      int32_t p_y{};
      InterfaceVersionTest_Foo_ParamsDataView input_data_view(params, message);
      
      if (success)
        p_x = input_data_view.x();
      if (success)
        p_y = input_data_view.y();
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            InterfaceVersionTest::Name_, 0, false);
        return false;
      }
      auto callback =
          InterfaceVersionTest_Foo_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Foo(        
        std::move(p_x), 
        std::move(p_y), std::move(callback));
      return true;
    }
  }
  return false;
}
